// The counter's gate the stock firmware uses: CTA from 0xE00000, so
// 0x200000 SYSCLKs (0.43 s at 4.9152 MHz).
static constexpr uint32_t kGateCycles = 0x200000u;

// Loads a 0x20..0x33 image into a configuration.
template <const uint8_t (&Img)[20]>
void load(hy3131::Config& c) {
	for (uint8_t i = 0; i < 20; i++) c.reg[i] = Img[i];
	c.gateCycles = kGateCycles;
}

struct RangeCal {
	meter::Function function;
	uint8_t         range;
	uint8_t         stockMode;
	uint8_t         stockRange;
	float           nominalCountsPerDigit;   // 0: not an AD1 range (the counter)
};

